<?php declare(strict_types=1);
use Kulturhus\Native\Shared\Db;
use Kulturhus\Native\Cms\{TreeCopyJobs,Pages,PageReferences};
$jobs=new TreeCopyJobs($db,$admin);$editorJobs=new TreeCopyJobs($db,$editor);
$jobField=$model->saveField(['key'=>'role_job_value','label'=>'Own protected copy checkpoint','type'=>'text','access'=>['read'=>'manage','edit'=>'manage']]);$model->saveTemplate(['key'=>'role_job_source','label'=>'Own protected job template','fields'=>['role_job_value']]);$jobSource=$pages->save(['title'=>'Own protected checkpoint source','slug'=>'role-job-source','template'=>'role_job_source','custom_fields'=>['role_job_value'=>'Exact checkpoint private original']]);
$beforeJobs=(int)$db->query('SELECT COUNT(*) FROM khcms_tree_copy_jobs')->fetchColumn();rejects(fn()=>$editorJobs->create($jobSource['id'],$jobSource['version'],['title'=>'Forbidden selected job','slug'=>'role-job-forbidden']),DomainException::class,'actual resumable tree selection cannot stage inaccessible field originals');check((int)$db->query('SELECT COUNT(*) FROM khcms_tree_copy_jobs')->fetchColumn()===$beforeJobs,'rejected protected subtree selection stores no partial job or snapshot');
Db::run($db,"INSERT INTO native_grants(actor_id,module,capability) VALUES('editor','website','manage')");$job=$editorJobs->create($jobSource['id'],$jobSource['version'],['title'=>'Own authorized checkpoint copy','slug'=>'role-job-authorized']);$sourceRow=Db::run($db,'SELECT * FROM khcms_pages WHERE id=?',[$jobSource['id']])->fetch();$sourceRevisions=Db::run($db,'SELECT * FROM khcms_revisions WHERE page_id=? ORDER BY revision',[$jobSource['id']])->fetchAll();Db::run($db,"DELETE FROM native_grants WHERE actor_id='editor' AND module='website' AND capability='manage'");
rejects(fn()=>$editorJobs->advance($job['id'],$job['version']),DomainException::class,'actual checkpoint rechecks a field grant revoked after selection');check($jobs->get($job['id'])['version']===$job['version']&&$jobs->get($job['id'])['next_index']===0,'revoked advance leaves the exact selected job version and checkpoint unchanged');
$job=$jobs->advance($job['id'],$job['version']);rejects(fn()=>$editorJobs->complete($job['id'],$job['version'],true),DomainException::class,'actual final atomic insertion rechecks current field rights after successful preparation');check(!Db::run($db,"SELECT 1 FROM khcms_pages WHERE slug='role-job-authorized'")->fetchColumn(),'revoked finalization leaves no partial destination original');$job=$jobs->complete($job['id'],$job['version'],true);$copy=$pages->get($job['root_copy_id']);check($job['status']==='completed'&&$copy['published_revision']===null&&$copy['custom_fields']['role_job_value']==='Exact checkpoint private original'&&$copy['field_definitions']['role_job_value']===$jobSource['field_definitions']['role_job_value'],'fully authorized resumed checkpoint preserves exact scalar access and creates only a private copy');check(Db::run($db,'SELECT * FROM khcms_pages WHERE id=?',[$jobSource['id']])->fetch()===$sourceRow&&Db::run($db,'SELECT * FROM khcms_revisions WHERE page_id=? ORDER BY revision',[$jobSource['id']])->fetchAll()===$sourceRevisions,'all checkpoint grant/revocation/finalization operations preserve exact source originals');
$target=$pages->save(['title'=>'Own target of protected field link','slug'=>'role-ref-target']);$linkField=$model->saveField(['key'=>'role_page_link','label'=>'Own protected link','type'=>'page-reference','access'=>['read'=>'manage','edit'=>'manage']]);$model->saveTemplate(['key'=>'role_link_source','label'=>'Own protected link source','fields'=>['role_page_link']]);$linked=$pages->save(['title'=>'Known readable source with private relation','slug'=>'role-link-source','template'=>'role_link_source','custom_fields'=>['role_page_link'=>$target['id']]]);$incoming=(new PageReferences($db,$editor))->incoming($target['id']);check(count($incoming)===1&&!empty($incoming[0]['restricted'])&&!str_contains(json_encode($incoming,JSON_THROW_ON_ERROR),$linked['id']),'incoming dependency DTO preserves a generic protected blocker without revealing a forbidden field relation');
check((new PageReferences($db,$admin))->incoming($target['id'])[0]['id']===$linked['id'],'authorized incoming dependency observation still identifies its true original source');
